        a0 = (v8){0} + a[1]; c10 += a0 * b0; c11 += a0 * b1;
        a0 = (v8){0} + a[2]; c20 += a0 * b0; c21 += a0 * b1;
        a0 = (v8){0} + a[3]; c30 += a0 * b0; c31 += a0 * b1;
