                    int j = 0;
                    for (; j < nr; j++) dst[(size_t)k * NR + j] = src[(size_t)k * n + j];
                    for (; j < NR; j++) dst[(size_t)k * NR + j] = 0.0f;
                }
            }
        }

        #pragma omp for schedule(dynamic, 1) collapse(2)
        for (int ti = 0; ti < ntm; ti++) {
            for (int tj = 0; tj < ntn; tj++) {
                int ic = ti * MC, jc = tj * NC;
                int mc = n - ic < MC ? n - ic : MC;
                int nc = n - jc < NC ? n - jc : NC;
                for (int pc = 0; pc < n; pc += KC) {
                    int kc = n - pc < KC ? n - pc : KC;
                    int accum = pc > 0;
                    for (int jr = 0; jr < nc; jr += NR) {
                        int nr = nc - jr < NR ? nc - jr : NR;
                        const float *bp = Bp + (size_t)((jc + jr) / NR) * n * NR + (size_t)pc * NR;
                        for (int ir = 0; ir < mc; ir += MR) {
                            int mr = mc - ir < MR ? mc - ir : MR;
                            const float *ap = Ap + (size_t)((ic + ir) / MR) * n * MR + (size_t)pc * MR;
                            kernel(kc, ap, bp, C + (size_t)(ic + ir) * n + jc + jr,
